1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8" />
5	  <meta http-equiv="X-UA-Compatible" content="IE=edge" />
6	  <meta name="viewport" content="width=device-width, initial-scale=1" />
7	  <title>AniJS demo</title>
8	
9	  <link rel="stylesheet" href="https://anijs.github.io/lib/anicollection/anicollection.css" />
10	  <link rel="stylesheet" href="demo.css"/>
11	
12	  <script src="../dist/gridstack-all.js"></script>
13	  <script src="https://cdnjs.cloudflare.com/ajax/libs/AniJS/0.9.3/anijs.js"></script>
14	</head>
15	<body>
16	  <div class="container-fluid">
17	    <h1>AniJS demo</h1>
18	    <div>
19	      <a onClick="addWidget()" class="btn btn-primary" href="#">Add Widget</a>
20	    </div>
21	    <h4>Widget added</h4>
22	    <br>
23	    <div class="grid-stack"></div>
24	  </div>
25	
26	  <script type="text/javascript">
27	    let grid = GridStack.init();
28	    let self = this;
29	    grid.on('added', function(e, items) {
30	      // add anijs data to gridstack item
31	      for (let i = 0; i < items.length; i++) {
32	        items[i].el.setAttribute('data-anijs', 'if: added, do: swing animated, after: $removeAnimations, on: $gridstack');
33	      }
34	      AniJS.run();
35	      self.gridstackNotifier = AniJS.getNotifier('gridstack');
36	      // fire added event!
37	      self.gridstackNotifier.dispatchEvent('added');
38	    });
39	
40	    function addWidget() {
41	      grid.addWidget({w: Math.floor(1 + 3 * Math.random()), h: Math.floor(1 + 3 * Math.random())});
42	    };
43	
44	    let animationHelper = AniJS.getHelper();
45	
46	    //Defining removeAnimations to remove existing animations
47	    animationHelper.removeAnimations = function(e, animationContext) {
48	      document.querySelectorAll('.grid-stack-item').forEach( function(el) {
49	        el.removeAttribute('data-anijs');
50	      });
51	    }
52	
53	    addWidget();
54	  </script>
55	</body>
56	</html>
