1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta http-equiv="X-UA-Compatible" content="IE=edge">
6	  <meta name="viewport" content="width=device-width, initial-scale=1">
7	  <title>Column grid demo</title>
8	
9	  <link rel="stylesheet" href="demo.css"/>
10	  <script src="../dist/gridstack-all.js"></script>
11	</head>
12	<body>
13	  <div class="container-fluid">
14	    <h1>column() grid demo (fix cellHeight)</h1>
15	    <div><span>Number of Columns:</span> <span id="column-text">12</span></div>
16	    <div>
17	      <label>Choose re-layout:</label>
18	      <select onchange="setLayout(this.value)">
19	        <option value="list">list</option>
20	        <option value="compact">compact</option>
21	        <option value="moveScale">move + scale</option>
22	        <option value="move">move</option>
23	        <option value="scale">scale</option>
24	        <option value="none">none</option>
25	        <option value="custom">custom</option>
26	      </select>
27	    </div>
28	    <div>
29	      load:
30	      <a onClick="grid.removeAll().load(list)" class="btn btn-primary" href="#">list</a>
31	      <a onClick="grid.removeAll().load(test1)" class="btn btn-primary" href="#">case 1</a>
32	      <a onClick="random()" class="btn btn-primary" href="#">random</a>
33	      <a onClick="addWidget()" class="btn btn-primary" href="#">Add Widget</a>
34	      column:
35	      <a onClick="column(1)" class="btn btn-primary" href="#">1</a>
36	      <a onClick="column(2)" class="btn btn-primary" href="#">2</a>
37	      <a onClick="column(3)" class="btn btn-primary" href="#">3</a>
38	      <a onClick="column(4)" class="btn btn-primary" href="#">4</a>
39	      <a onClick="column(6)" class="btn btn-primary" href="#">6</a>
40	      <a onClick="column(8)" class="btn btn-primary" href="#">8</a>
41	      <a onClick="column(10)" class="btn btn-primary" href="#">10</a>
42	      <a onClick="column(12)" class="btn btn-primary" href="#">12</a>
43	    </div>
44	    <br>
45	    <div class="grid-stack"></div>
46	  </div>
47	
48	  <script type="text/javascript">
49	    // NOTE: REAL apps would sanitize-html or DOMPurify before blinding setting innerHTML. see #2736
50	    GridStack.renderCB = function(el, w) {
51	      el.innerHTML = w.content;
52	    };
53	
54	    let test1 = [ // DOM order will be 0,1,2,3,4,5,6 vs column1 = 0,1,4,3,2,5,6
55	      /* match karma testing
56	      {x: 0, y: 0, w: 4, h: 2},
57	      {x: 4, y: 0, w: 4, h: 4},
58	      {text: ' auto'},
59	      */
60	      {x: 0, y: 0, w: 2, h: 2},
61	      {x: 2, y: 0, w: 2},
62	      {x: 5, y: 1},
63	      {x: 5, y: 0, w: 2},
64	      // {x: 0, y: 0}, // conflict
65	      {text: ' auto'}, // autoPosition testing
66	      // {x: 4, y: 0}, // same auto-pos
67	      {x: 5, y: 3, w: 2},
68	      {x: 0, y: 4, w: 12}
69	    ];
70	    let list = [{h:2},{},{},{},{},{},{},{},{},{w:2},{},{},{},{},{},{}];
71	    list.forEach((n,i) => {
72	      n.content = '<button onClick="grid.removeWidget(this.parentNode.parentNode)">X</button><br>' + ++i;
73	    });
74	    let count = 0;
75	    test1.forEach(n => {
76	      n.content = '<button onClick="grid.removeWidget(this.parentNode.parentNode)">X</button><br>' + count++ + (n.text ? n.text : '');
77	    });
78	
79	    let grid = GridStack.init({
80	      float: true,
81	      cellHeight: 100 // fixed as default 'auto' (square) makes it hard to test 1-3 column in actual large windows tests
82	    }).load(list);
83	    let text = document.querySelector('#column-text');
84	    let layout = 'list';
85	
86	    grid.on('added removed change', function(e, items) {
87	      let str = '';
88	      items.forEach(function(item) { str += ' (x,y)=' + item.x + ',' + item.y; });
89	      console.log(e.type + ' ' + items.length + ' items:' + str );
90	    });
91	
92	
93	    function random() {
94	      grid.removeAll();
95	      count = 0;
96	      for (i=0; i<8; i++) addWidget(true);
97	    }
98	
99	    function addWidget() {
100	      let n = {
101	        w: Math.round(1 + 3 * Math.random()),
102	        h: Math.round(1 + 3 * Math.random()),
103	        content: '<button onClick="grid.removeWidget(this.parentNode.parentNode)">X</button><br>' + count++,
104	      };
105	      grid.addWidget(n);
106	    };
107	
108	    function column(n) {
109	      grid.column(n, layout);
110	      text.innerHTML = n;
111	    }
112	    // dummy test method that moves items to the right each new layout... grid engine will validate those values (can't be neg or out of bounds) anyway...
113	    function columnLayout(column, oldColumn, nodes, oldNodes) {
114	      oldNodes.forEach(n => {
115	        n.x = n.x + 1;
116	        nodes.push(n);
117	      });
118	      oldNodes.length = 0;
119	    }
120	    function setLayout(name) {
121	      layout = name === 'custom' ? this.columnLayout : name;
122	    }
123	  </script>
124	</body>
125	</html>
126

