1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta http-equiv="X-UA-Compatible" content="IE=edge">
6	  <meta name="viewport" content="width=device-width, initial-scale=1">
7	  <title>Float grid demo</title>
8	
9	  <link rel="stylesheet" href="demo.css"/>
10	  <script src="../dist/gridstack-all.js"></script>
11	
12	</head>
13	<body>
14	  <div class="container-fluid">
15	    <h1>Float grid demo</h1>
16	    <div>
17	      <a class="btn btn-primary" onClick="addNewWidget()" href="#">Add Widget</a>
18	      <a class="btn btn-primary" onClick="makeNewWidget()" href="#">Make Widget</a>
19	      <a class="btn btn-primary" onclick="toggleFloat()" id="float" href="#">float: true</a>
20	    </div>
21	    <br><br>
22	    <div class="grid-stack"></div>
23	  </div>
24	  <script src="events.js"></script>
25	  <script type="text/javascript">
26	    let grid = GridStack.init({
27	      float: true, 
28	      // disableResize: true, // TEST no resizing, but dragging
29	      resizable: { handles: 'all'} // do all sides for testing
30	    });
31	    addEvents(grid);
32	
33	    let items = [
34	      {x: 1, y: 1}, //, locked:true, content:"locked"},
35	      {x: 2, y: 2, w: 3},
36	      {x: 4, y: 2},
37	      {x: 3, y: 1, h: 2},
38	      {x: 0, y: 6, w: 2, h: 2}
39	    ];
40	    let count = 0;
41	
42	    getNode = function() {
43	      let n = items[count] || {
44	        x: Math.round(12 * Math.random()),
45	        y: Math.round(5 * Math.random()),
46	        w: Math.round(1 + 3 * Math.random()),
47	        h: Math.round(1 + 3 * Math.random())
48	      };
49	      n.content = n.content || String(count);
50	      count++;
51	      return n;
52	    };
53	
54	    addNewWidget = function() {
55	      let w = grid.addWidget(getNode());
56	    };
57	
58	    makeNewWidget = function() {
59	      let n = getNode();
60	      let doc = document.implementation.createHTMLDocument();
61	      doc.body.innerHTML = `<div class="item" gs-x="${n.x}" gs-y="${n.y}" gs-w="${n.w || 1}" gs-h="${n.h || 1}"><div class="grid-stack-item-content">${n.content}</div></div>`;
62	      let el = doc.body.children[0];
63	      grid.el.appendChild(el);
64	      // example showing when DOM is created elsewhere (eg Angular/Vue/React) and GS is used to convert to a widget
65	      let w = grid.makeWidget(el);
66	    };
67	
68	    toggleFloat = function() {
69	      grid.float(! grid.getFloat());
70	      document.querySelector('#float').innerHTML = 'float: ' + grid.getFloat();
71	    };
72	    addNewWidget();
73	  </script>
74	</body>
75	</html>
