1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta http-equiv="X-UA-Compatible" content="IE=edge">
6	  <meta name="viewport" content="width=device-width, initial-scale=1">
7	  <title>Grid Lines demo</title>
8	
9	  <link rel="stylesheet" href="demo.css"/>
10	  <script src="../dist/gridstack-all.js"></script>
11	  <style>
12	    .controls {
13	      display: flex;
14	      align-items: center;
15	      gap: 24px;
16	      padding: 12px 0 16px;
17	      flex-wrap: wrap;
18	    }
19	    .control-group {
20	      display: flex;
21	      align-items: center;
22	      gap: 8px;
23	    }
24	    .control-group label {
25	      font-weight: 500;
26	      white-space: nowrap;
27	    }
28	    input[type=range] {
29	      width: 140px;
30	    }
31	    .val-badge {
32	      display: inline-block;
33	      min-width: 2.5em;
34	      font-family: monospace;
35	      font-size: 0.9em;
36	      background: #eee;
37	      border-radius: 4px;
38	      padding: 1px 5px;
39	      text-align: center;
40	    }
41	
42	    /* ── Grid lines ───────────────────────────────────────────────
43	       Uses CSS custom properties already set by GridStack on the
44	       grid element:
45	         --gs-column-width  (e.g. 8.333%  for a 12-col grid)
46	         --gs-cell-height   (e.g. 70px)
47	       Two extra vars control appearance and can be set via JS or
48	       overridden in your own stylesheet:
49	         --gs-line-color     default: rgba(0,0,0,0.15)
50	         --gs-line-thickness default: 1px
51	    ──────────────────────────────────────────────────────────── */
52	    .grid-stack.gs-show-grid-lines {
53	      background-image:
54	        linear-gradient(
55	          to right,
56	          var(--gs-line-color, rgba(0,0,0,.15)) var(--gs-line-thickness, 1px),
57	          transparent var(--gs-line-thickness, 1px)
58	        ),
59	        linear-gradient(
60	          to bottom,
61	          var(--gs-line-color, rgba(0,0,0,.15)) var(--gs-line-thickness, 1px),
62	          transparent var(--gs-line-thickness, 1px)
63	        );
64	      background-size: var(--gs-column-width) var(--gs-cell-height);
65	      background-position: top left;
66	    }
67	  </style>
68	</head>
69	<body>
70	  <div style="padding: 0 20px">
71	    <h1>Grid Lines demo</h1>
72	    <p>Toggle grid lines on/off and adjust color and thickness using the controls below.
73	       No JS changes to GridStack itself are needed — the trick relies on the CSS custom
74	       properties <code>--gs-column-width</code> and <code>--gs-cell-height</code> that
75	       GridStack already sets on the element.</p>
76	
77	    <div class="controls">
78	      <div class="control-group">
79	        <label for="toggle">Show lines</label>
80	        <input type="checkbox" id="toggle" checked>
81	      </div>
82	      <div class="control-group">
83	        <label for="colorPicker">Color</label>
84	        <input type="color" id="colorPicker" value="#0000ff">
85	        <input type="range" id="opacity" min="0" max="100" value="20" title="Opacity">
86	        <span class="val-badge" id="opacityVal">20%</span>
87	      </div>
88	      <div class="control-group">
89	        <label for="thickness">Thickness</label>
90	        <input type="range" id="thickness" min="1" max="8" value="1" step="0.5">
91	        <span class="val-badge" id="thicknessVal">1px</span>
92	      </div>
93	      <div class="control-group">
94	        <label for="columns">Columns</label>
95	        <input type="range" id="columns" min="2" max="24" value="12" step="1">
96	        <span class="val-badge" id="columnsVal">12</span>
97	      </div>
98	    </div>
99	
100	    <div class="grid-stack gs-show-grid-lines" id="grid"></div>
101	  </div>
102	
103	  <script>
104	    const grid = GridStack.init({ column: 12, cellHeight: 70, animate: true });
105	    grid.load([
106	      {x:0, y:0, w:2, h:2, content:'A'},
107	      {x:2, y:0, w:3, h:1, content:'B'},
108	      {x:5, y:0, w:2, h:3, content:'C'},
109	      {x:2, y:1, w:2, h:2, content:'D'},
110	      {x:7, y:0, w:5, h:2, content:'E'},
